//! The runtime of the safe Rust API generated by ferrobridge.
//!
//! A generated `bridge.rs` has two layers: cxx's raw `ffi` module and the safe layer on top
//! of it. All errors in the safe layer come back as a single type, [`Error`]. So errors from
//! APIs generated from different headers combine with `?`.
//!
//! ```
//! fn error_summary(error: &ferrobridge::Error) -> String {
//!     format!("{error}") // e.g. "own::Widget::adopt: engine failure"
//! }
//! ```

#![forbid(unsafe_code)]

use std::fmt;

/// The error of a call in the safe layer. Every case names the C++ item the error came from.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum Error {
    /// The C++ code threw an exception.
    Cpp {
        /// The C++ item the exception came from (e.g. `own::Widget::adopt`).
        item: &'static str,
        /// The exception's message (`std::exception::what()`).
        message: String,
    },
    /// A `std::string` from C++ is not valid UTF-8; it could not be turned into a Rust `String`/`&str`.
    Utf8 {
        /// The C++ item that returned the string.
        item: &'static str,
    },
    /// An owning pointer that cannot be null came back null (a bug in ferrobridge or in C++).
    NullPointer {
        /// The C++ item that returned the pointer.
        item: &'static str,
    },
    /// A value not defined in the enum came from C++.
    UnknownEnumValue {
        /// The enum's full C++ name (e.g. `io::Mode`).
        ty: &'static str,
        /// The value that came.
        value: i128,
    },
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Cpp { item, message } => write!(f, "{item}: {message}"),
            Error::Utf8 { item } => write!(f, "{item}: the C++ string is not valid UTF-8"),
            Error::NullPointer { item } => write!(f, "{item}: beklenmeyen null pointer"),
            Error::UnknownEnumValue { ty, value } => {
                write!(f, "{ty}: an undefined enum value came from C++ ({value})")
            }
        }
    }
}

impl std::error::Error for Error {}

/// Includes, at this point, the bridge generated in `build.rs` with the `generate` feature of
/// `ferrobridge-build`. The name is the one given to `ferrobridge_build::Generate::new`.
///
/// ```ignore
/// pub mod crc {
///     ferrobridge::include_bridge!("crc");
/// }
/// ```
///
/// The generated file is `$OUT_DIR/ferrobridge/<name>/bridge.rs`; its unbound items and the
/// assumptions based on annotations are listed at the top of the file.
///
/// The file's cxx layer (`ffi`) contains `unsafe extern` blocks. If the crate forbids
/// `unsafe_code`, the module containing the bridge needs `#[allow(unsafe_code)]` (`forbid` cannot be relaxed).
#[macro_export]
macro_rules! include_bridge {
    ($name:literal) => {
        include!(concat!(
            env!("OUT_DIR"),
            "/ferrobridge/",
            $name,
            "/bridge.rs"
        ));
    };
}

/// The result type of the safe layer.
pub type Result<T> = std::result::Result<T, Error>;

/// Helpers used by the generated code. Not a stable API; do not use directly.
#[doc(hidden)]
pub mod __private {
    use cxx::kind::Trivial;
    use cxx::vector::VectorElement;
    use cxx::{CxxString, CxxVector, ExternType, UniquePtr};

    use super::{Error, Result};

    /// Turns a `cxx::Exception` into an [`Error::Cpp`], together with the C++ item it came from.
    pub fn cpp(item: &'static str) -> impl FnOnce(cxx::Exception) -> Error {
        move |exception| Error::Cpp {
            item,
            message: exception.what().to_owned(),
        }
    }

    /// Checks a `UniquePtr` that must not be null.
    pub fn non_null<T>(item: &'static str, ptr: UniquePtr<T>) -> Result<UniquePtr<T>>
    where
        T: cxx::memory::UniquePtrTarget,
    {
        if ptr.is_null() {
            Err(Error::NullPointer { item })
        } else {
            Ok(ptr)
        }
    }

    /// A borrowed UTF-8 view of a C++ string.
    pub fn str_ref<'a>(item: &'static str, value: &'a CxxString) -> Result<&'a str> {
        value.to_str().map_err(|_| Error::Utf8 { item })
    }

    /// Copies an owned C++ string into a Rust `String`.
    pub fn string(item: &'static str, value: UniquePtr<CxxString>) -> Result<String> {
        let value = non_null(item, value)?;
        str_ref(item, &value).map(str::to_owned)
    }

    /// Copies an owned vector of numbers into a Rust `Vec`.
    pub fn vec<T>(item: &'static str, value: UniquePtr<CxxVector<T>>) -> Result<Vec<T>>
    where
        T: VectorElement + Copy,
    {
        let value = non_null(item, value)?;
        Ok(value.iter().copied().collect())
    }

    /// Copies an owned vector of strings into a `Vec<String>`.
    pub fn strings(
        item: &'static str,
        value: UniquePtr<CxxVector<CxxString>>,
    ) -> Result<Vec<String>> {
        let value = non_null(item, value)?;
        value
            .iter()
            .map(|s| str_ref(item, s).map(str::to_owned))
            .collect()
    }

    /// Copies a Rust slice into a new C++ vector.
    pub fn cxx_vector<T>(values: &[T]) -> UniquePtr<CxxVector<T>>
    where
        T: VectorElement + ExternType<Kind = Trivial> + Copy,
    {
        let mut vector = CxxVector::new();
        for value in values {
            vector.pin_mut().push(*value);
        }
        vector
    }

    /// The error for a value not defined in the enum.
    pub fn unknown_enum(ty: &'static str, value: impl Into<i128>) -> Error {
        Error::UnknownEnumValue {
            ty,
            value: value.into(),
        }
    }
}

#[cfg(test)]
mod tests {
    use cxx::{CxxString, CxxVector, UniquePtr, let_cxx_string};

    use super::__private::*;
    use super::*;

    #[test]
    fn errors_name_the_cpp_item() {
        let cases = [
            (
                Error::Cpp {
                    item: "own::Widget::adopt",
                    message: "engine failure".to_owned(),
                },
                "own::Widget::adopt: engine failure",
            ),
            (
                Error::Utf8 {
                    item: "text::greet",
                },
                "text::greet: the C++ string is not valid UTF-8",
            ),
            (
                Error::NullPointer { item: "own::make" },
                "own::make: beklenmeyen null pointer",
            ),
            (
                unknown_enum("io::Mode", 7_i32),
                "io::Mode: an undefined enum value came from C++ (7)",
            ),
        ];
        for (error, shown) in cases {
            assert_eq!(error.to_string(), shown);
        }
    }

    #[test]
    fn enum_values_of_every_width_fit() {
        assert_eq!(
            unknown_enum("e", u64::MAX),
            Error::UnknownEnumValue {
                ty: "e",
                value: i128::from(u64::MAX)
            }
        );
        assert_eq!(
            unknown_enum("e", i16::MIN),
            Error::UnknownEnumValue {
                ty: "e",
                value: -32768
            }
        );
    }

    #[test]
    fn null_unique_ptrs_are_errors() {
        let null: UniquePtr<CxxString> = UniquePtr::null();
        assert_eq!(
            string("f", null).unwrap_err(),
            Error::NullPointer { item: "f" }
        );
        let null: UniquePtr<CxxVector<i32>> = UniquePtr::null();
        assert_eq!(
            vec("g", null).unwrap_err(),
            Error::NullPointer { item: "g" }
        );
    }

    #[test]
    fn strings_are_checked_for_utf8() {
        let_cxx_string!(good = "café ✓");
        assert_eq!(str_ref("f", &good).unwrap(), "café ✓");
        let_cxx_string!(bad = [0xff_u8, 0xfe]);
        assert_eq!(str_ref("f", &bad).unwrap_err(), Error::Utf8 { item: "f" });
    }

    #[test]
    fn number_vectors_round_trip() {
        let vector = cxx_vector(&[1.5_f64, -2.0, 4.25]);
        assert_eq!(vector.len(), 3);
        assert_eq!(vec("f", vector).unwrap(), [1.5, -2.0, 4.25]);
        assert!(cxx_vector::<i32>(&[]).is_empty());
    }
}
